function header(isStudio=false){return `<header class="${isStudio?'studio-topbar':'topnav site-container'}">${htmlLogo()}${!isStudio?`<nav class="nav-links"><a href="#how">${h('navHow')}</a><a href="#templates">${h('navTemplates')}</a><a href="/dashboard" data-nav="/dashboard">${h('navDashboard')}</a></nav>`:''}<div class="${isStudio?'studio-actions':'nav-actions'}">${isStudio?`<span class="status-pill ${CLOUD_READY?'cloud':''}">${CLOUD_READY?h('cloudMode'):h('demoMode')}</span>`:''}<select class="lang-menu ${isStudio?'studio-lang':''}" aria-label="Language" data-language><option value="ar" ${lang==='ar'?'selected':''}>AR</option><option value="en" ${lang==='en'?'selected':''}>EN</option><option value="fr" ${lang==='fr'?'selected':''}>FR</option></select>${!isStudio?`<a href="/dashboard" data-nav="/dashboard" class="btn btn-line">${h('navDashboard')}</a>`:''}${isStudio?`<a href="/dashboard" data-nav="/dashboard" class="btn btn-line">${h('navDashboard')}</a>`:`<a href="/create" data-nav="/create" class="btn btn-main">${h('navStart')} ${ic('arrow','icon-xs')}</a>`}</div></header>`}
function renderHome(){document.title='NEXORA Studio | '+h('heroC');const catCards=Object.entries(TYPES).map(([id,c],i)=>`<button class="category-card" data-create-category="${id}" style="--cat:${c.color};--cardGlow:${c.color}" aria-label="${esc(c[lang])}"><span class="cat-number">0${i+1} / ${c.name}</span><span class="cat-ico">${ic(c.icon)}</span><h3>${esc(c[lang])}</h3><p>${esc(c.desc[lang])}</p><span class="cat-arrow">${h('tryTemplate')} ${ic('arrow','icon-xs')}</span></button>`).join('');APP.innerHTML=`<div class="main-shell">${header()}<main><section class="hero site-container"><div class="hero-copy"><span class="eyebrow">${h('heroEyebrow')}</span><h1>${h('heroA')}<br>${h('heroB')}<br><span class="gradient">${h('heroC')}</span></h1><p class="hero-description">${h('heroDesc')}</p><div class="hero-buttons"><a class="btn btn-main" href="/create" data-nav="/create">${ic('sparkle')} ${h('heroBtn')} ${ic('arrow','icon-xs')}</a><a class="btn btn-glass" href="#templates">${h('heroExplore')} ${ic('right','icon-xs')}</a></div><div class="hero-notes"><span>${ic('check')} ${h('n1')}</span><span>${ic('check')} ${h('n2')}</span><span>${ic('check')} ${h('n3')}</span></div></div><div class="hero-art"><div class="halo-glow"></div><div class="orbit"></div><div class="orbit two"></div><div class="mock-stack"><div class="mock-phone"><div class="top-notch"></div><div class="mock-content"><div class="mock-avatar">N.</div><h3>YOUR NAME</h3><p>DESIGNER • CREATOR • INNOVATOR</p><div class="mock-link purple">My portfolio ${ic('arrow','icon-xs')}</div><div class="mock-link">Instagram ${ic('arrow','icon-xs')}</div><div class="mock-link">Projects ${ic('arrow','icon-xs')}</div><div class="mock-link">Let’s connect ${ic('arrow','icon-xs')}</div></div></div></div><div class="float-note one">${ic('sparkle')} PERSONALIZED DESIGN<span>4 SPECIALIZED WORLDS</span></div><div class="float-note two">${ic('check')} READY TO SHARE<span>YOUR DIGITAL PRESENCE</span></div></div></section><section class="section site-container" id="templates"><div class="section-top"><div><span class="eyebrow">${h('templatesOver')}</span><h2>${h('templatesTitle')}</h2></div><p>${h('templatesDesc')}</p></div><div class="category-grid">${catCards}</div></section><section class="section site-container" id="how"><div class="section-top"><div><span class="eyebrow">${h('stepsOver')}</span><h2>${h('stepsTitle')}</h2></div></div><div class="steps-grid">${[1,2,3].map(i=>`<article class="step-card"><div class="step-number">0${i}.</div><h3>${h('step'+i)}</h3><p>${h('step'+i+'d')}</p></article>`).join('')}</div></section><section class="site-container"><div class="launch-banner"><div><h2>${h('bannerTitle')}</h2><p>${h('bannerDesc')}</p></div><a class="btn btn-main" href="/create" data-nav="/create">${h('bannerBtn')} ${ic('arrow')}</a></div></section></main><footer class="footer site-container"><span>© ${new Date().getFullYear()} NEXORA STUDIO</span><span>${h('footer')}</span></footer></div>`}
function profileLinks(p){let links=(p.links||[]).filter(x=>x.title?.trim()&&safeWebsite(x.url));return links.map((x,i)=>`<a class="profile-link" href="${esc(safeWebsite(x.url))}" target="_blank" rel="noopener noreferrer"><span class="prof-icon">${ic(i%3===0?'globe':i%3===1?'link':'arrow')}</span><strong>${esc(x.title)}</strong>${ic('arrow')}</a>`).join('')}
function renderProfile(p,{example=false}={}){p=p||newProfile();const c=TYPES[p.category]||TYPES.academic;const locale=['ar','en','fr'].includes(p.locale)?p.locale:'ar';const name=p.name?.trim()|| (example?h('sampleName',locale):'');const bio=p.bio?.trim()||(example?h('sampleBio',locale):'');const avatarUrl=p.avatar?.startsWith('data:image/jpeg;base64,')?p.avatar:safeWebsite(p.avatar);const initials=(name.trim().split(/\s+/).filter(Boolean).slice(0,2).map(x=>x.charAt(0)).join('')||'N').toUpperCase();const socials=['instagram','linkedin','youtube','tiktok','facebook','website'].filter(k=>socialHref(k,p.socials?.[k]));if(p.email&&socialHref('email',p.email))socials.push('email');if(p.whatsapp&&socialHref('whatsapp',p.whatsapp))socials.push('whatsapp');let highlights=(p.features||[]).filter(x=>x.title?.trim()).slice(0,20);return `<article class="profile-viewport t-${esc(p.category)}" data-highlight="${esc(p.accent||'violet')}" dir="${locale==='ar'?'rtl':'ltr'}" lang="${locale}"><div class="profile-topline"><span class="pmark"><span class="pmini">N.</span> ${esc(c.name)}</span>${ic('sparkle','icon-xs')}</div><div class="profile-hero"><div class="profile-avatar">${avatarUrl?`<img src="${esc(avatarUrl)}" alt="${esc(name)}" loading="lazy" onerror="this.remove()">`:esc(initials)}</div><div class="profile-kicker">${esc(c.name)}</div><h1>${esc(name)}</h1>${p.headline?`<div class="profile-role">${esc(p.headline)}</div>`:''}${bio?`<p class="profile-bio">${esc(bio)}</p>`:''}${p.location?`<div class="profile-location">${ic('location','icon-xs')} ${esc(p.location)}</div>`:''}</div>${socials.length?`<div class="profile-socials">${socials.map(k=>`<a aria-label="${esc(k)}" title="${esc(k)}" href="${esc(socialHref(k,k==='email'?p.email:k==='whatsapp'?p.whatsapp:p.socials[k]))}" target="_blank" rel="noopener noreferrer">${ic(k==='website'?'globe':k==='email'?'mail':k)}</a>`).join('')}</div>`:''}<div class="profile-section-title"><span>${esc(h('profileLinks',locale))}</span><span>${(p.links||[]).filter(x=>x.title&&safeWebsite(x.url)).length.toString().padStart(2,'0')}</span></div>${profileLinks(p)||`<div style="text-align:center;padding:24px;color:var(--secondary);font-size:11px">${h('noLinks',locale)}</div>`}${highlights.length?`<div class="profile-section-title"><span>${esc(c.features[locale])}</span><span>${highlights.length.toString().padStart(2,'0')}</span></div>${highlights.map(f=>`<div class="profile-feature"><strong>${esc(f.title)}</strong>${f.description?`<p>${esc(f.description)}</p>`:''}${safeWebsite(f.url)?`<a href="${esc(safeWebsite(f.url))}" target="_blank" rel="noopener noreferrer">${h('visit',locale)} ${ic('arrow','icon-xs')}</a>`:''}</div>`).join('')}`:''}<div class="profile-footer">${h('powered',locale)} <span>✦ NEXORA</span></div></article>`}
function field(label,key,value,placeholder='',type='text',extra=''){return `<div class="form-group"><label class="form-label" for="field-${key}">${label}</label><input id="field-${key}" class="field" type="${type}" data-field="${key}" value="${esc(value||'')}" placeholder="${esc(placeholder)}" ${extra}></div>`}
function area(label,key,value,placeholder=''){return `<div class="form-group"><label class="form-label" for="field-${key}">${label}</label><textarea id="field-${key}" class="field area" data-field="${key}" placeholder="${esc(placeholder)}">${esc(value||'')}</textarea></div>`}
function socialsFields(){return ['instagram','linkedin','youtube','tiktok','facebook','website'].map(k=>`<div class="form-group"><label class="form-label">${esc(k[0].toUpperCase()+k.slice(1))}</label><input class="field compact" type="url" data-social="${k}" placeholder="https://${k==='website'?'example.com':k+'.com/...'}" value="${esc(builder.socials?.[k]||'')}"></div>`).join('')}
function identityFields(){return `<div class="form-group"><div class="form-label">${h('profileType')}</div><div class="category-select">${Object.entries(TYPES).map(([id,c])=>`<button type="button" class="category-option ${builder.category===id?'active':''}" data-change-category="${id}">${ic(c.icon)}<b>${esc(c[lang])}</b><small>${esc(c.name)}</small></button>`).join('')}</div></div><div class="group-card"><h3>${ic('user')} ${h('stepIdentity')}</h3>${field(h('displayName'),'name',builder.name,h('namePlaceholder'))}${field(h('role'),'headline',builder.headline)}${area(h('bio'),'bio',builder.bio,h('bioHint'))}<div class="form-split">${field(h('location'),'location',builder.location)}${field(h('email'),'email',builder.email,'contact@example.com','email')}</div>${field(h('whatsapp'),'whatsapp',builder.whatsapp,'213555123456')}<div class="form-group"><label class="form-label">${h('slug')}</label><div style="display:flex;align-items:center;gap:8px"><span style="font:600 11px 'DM Sans',sans-serif;color:#6a7186" dir="ltr">/p/</span><input class="field" data-field="slug" value="${esc(builder.slug||'')}" placeholder="page-name" maxlength="36" spellcheck="false" dir="ltr"></div><small class="form-hint">${h('slugHint')}</small></div></div>`}
function styleFields(){const colors={violet:'#ad97fa',mint:'#79ceb1',blue:'#8ebdfd',gold:'#d9bd88',coral:'#eea194',lime:'#c2e74e'};return `<div class="group-card"><h3>${ic('palette')} ${h('palette')}</h3><div class="palette-swatches">${Object.entries(colors).map(([key,color])=>`<button type="button" class="swatch ${builder.accent===key?'active':''}" style="background:${color}" data-accent="${key}" aria-label="${key}" title="${key}"></button>`).join('')}</div></div><div class="group-card"><h3>${ic('image')} ${h('profilePhoto')}</h3>${field(h('profilePhoto'),'avatar',builder.avatar?.startsWith('data:')?'':builder.avatar,'https://example.com/photo.jpg','url')}<div class="stack-actions"><label for="fileUpload" class="btn btn-soft" style="cursor:pointer">${ic('image')} ${h('uploadPhoto')}</label><input id="fileUpload" data-upload-photo type="file" accept="image/jpeg,image/png,image/webp" style="display:none"><button type="button" class="btn btn-line" data-clear-photo>${h('clearPhoto')}</button></div><p class="form-hint">${h('photoHint')}</p>${builder.avatar?`<img src="${esc(builder.avatar)}" alt="preview" style="height:84px;width:84px;border-radius:18px;object-fit:cover;margin-top:12px;border:1px solid #dde0ef">`:''}</div><div class="group-card"><h3>${ic('globe')} ${h('profileLang')}</h3><select class="field" data-field="locale"><option value="ar" ${builder.locale==='ar'?'selected':''}>العربية / Arabic</option><option value="fr" ${builder.locale==='fr'?'selected':''}>Français</option><option value="en" ${builder.locale==='en'?'selected':''}>English</option></select></div><div class="publish-warning">${h('stepStyleDesc')}</div>`}
function linksFields(){return `<div class="group-card"><h3>${ic('link')} ${h('quickLinks')}</h3><p class="form-hint" style="margin-bottom:13px">${h('quickLinksHint')}</p>${(builder.links||[]).map((item,i)=>`<div class="feature-item"><button type="button" class="delete-mini" data-remove-link="${i}" aria-label="${h('delete')}">${ic('trash','icon-xs')}</button><div style="padding-inline-end:35px"><label class="form-label">${h('linkName')}</label><input class="field compact" data-link="${i}" data-subfield="title" value="${esc(item.title)}" placeholder="${h('linkName')}" maxlength="80"></div><div style="margin-top:9px"><label class="form-label">${h('linkUrl')}</label><input class="field compact" type="url" data-link="${i}" data-subfield="url" value="${esc(item.url)}" placeholder="https://..." dir="ltr"></div></div>`).join('')}<button class="btn btn-soft" type="button" data-add-link>${ic('plus')} ${h('addLink')}</button></div><div class="group-card"><h3>${ic('share')} ${h('socials')}</h3><div class="form-split">${socialsFields()}</div></div><div class="group-card"><h3>${ic('grid')} ${h('features')}</h3>${(builder.features||[]).map((f,i)=>`<div class="feature-item"><button type="button" class="delete-mini" data-remove-feature="${i}" aria-label="${h('delete')}">${ic('trash','icon-xs')}</button><div style="padding-inline-end:35px"><label class="form-label">${h('featureTitle')}</label><input class="field compact" data-feature="${i}" data-subfield="title" value="${esc(f.title||'')}" maxlength="100"></div><div style="margin-top:9px"><label class="form-label">${h('featureDesc')}</label><textarea class="field area" style="min-height:67px" data-feature="${i}" data-subfield="description">${esc(f.description||'')}</textarea></div><div style="margin-top:9px"><label class="form-label">${h('optionalUrl')}</label><input class="field compact" data-feature="${i}" data-subfield="url" value="${esc(f.url||'')}" dir="ltr" placeholder="https://..."></div></div>`).join('')}<button type="button" class="btn btn-soft" data-add-feature>${ic('plus')} ${h('addFeature')}</button></div>`}
